using System;
using System.Collections.Generic;
using System.Drawing;
using System.Windows.Forms;
namespace WinterDesk {
internal sealed class WinterPanel:Form {
 readonly TableLayoutPanel grid;readonly Label status;readonly List<Tuple<WaterButton,ToolStripMenuItem>> links=new List<Tuple<WaterButton,ToolStripMenuItem>>();readonly WaterButton play,updateButton;readonly Label updateStatus;readonly UpdateClient updates;readonly IQuickKeys keys;bool moving;Point offset;
 protected override bool ShowWithoutActivation {get{return true;}}
 protected override CreateParams CreateParams {get{var p=base.CreateParams;p.ExStyle|=0x80|0x08000000;return p;}}
 internal WinterPanel(ContextMenuStrip menu,IQuickKeys quickKeys,UpdateClient updater){keys=quickKeys;updates=updater;Text="WinterDesk";Icon=WatercolorTheme.AppIcon;FormBorderStyle=FormBorderStyle.None;TopMost=true;ShowInTaskbar=false;Opacity=.76;BackColor=Color.FromArgb(247,240,222);BackgroundImage=WatercolorTheme.Paper;BackgroundImageLayout=ImageLayout.Stretch;ForeColor=Color.FromArgb(72,48,43);Font=new Font("Georgia",11);StartPosition=FormStartPosition.Manual;Width=260;Height=680;
  var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=6,Padding=new Padding(12),BackColor=Color.Transparent};root.RowStyles.Add(new RowStyle(SizeType.Absolute,48));root.RowStyles.Add(new RowStyle(SizeType.Absolute,42));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,70));root.RowStyles.Add(new RowStyle(SizeType.Absolute,48));root.RowStyles.Add(new RowStyle(SizeType.Absolute,78));Controls.Add(root);
  var header=new Label{Text="WinterDesk "+UpdateTrust.VersionText,Padding=new Padding(36,0,26,0),Dock=DockStyle.Fill,Font=new Font("Georgia",10,FontStyle.Bold),BackColor=Color.Transparent,TextAlign=ContentAlignment.MiddleLeft};header.Controls.Add(new PictureBox{Image=WatercolorTheme.AppIcon.ToBitmap(),SizeMode=PictureBoxSizeMode.Zoom,Size=new Size(30,30),Location=new Point(0,9),BackColor=Color.Transparent});header.MouseDown+=delegate(object sender,MouseEventArgs e){moving=true;offset=PointToClient(header.PointToScreen(e.Location));};header.MouseMove+=delegate(object sender,MouseEventArgs e){if(moving){var at=header.PointToScreen(e.Location);Location=new Point(at.X-offset.X,at.Y-offset.Y);}};header.MouseUp+=delegate{moving=false;};root.Controls.Add(header,0,0);
  var hide=new WaterButton{Text="—",Size=new Size(28,26),Location=new Point(Width-70,8)};hide.Click+=delegate{keys.SetEnabled(false);Hide();};header.Controls.Add(hide);
  var garland=new PictureBox{Dock=DockStyle.Fill,SizeMode=PictureBoxSizeMode.StretchImage,BackColor=Color.Transparent};garland.Image=WatercolorTheme.Garland(340,40,0,382);root.Controls.Add(garland,0,1);
  var body=new Panel{Dock=DockStyle.Fill,AutoScroll=true,BackColor=Color.Transparent};grid=new TableLayoutPanel{Dock=DockStyle.Top,AutoSize=true,ColumnCount=1,BackColor=Color.Transparent};grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));body.Controls.Add(grid);root.Controls.Add(body,0,2);int count=0;foreach(ToolStripItem item in menu.Items)AddItem(item,ref count);
  play=new WaterButton{Name="PlayMode",Text="ВКЛЮЧИТЬ ИГРОВОЙ РЕЖИМ",Dock=DockStyle.Fill,Font=new Font("Georgia",11,FontStyle.Bold),Margin=new Padding(3,5,3,5)};play.Click+=delegate{keys.SetEnabled(!keys.Enabled);RefreshStatus(null);};root.Controls.Add(play,0,3);
  status=new Label{Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter,BackColor=Color.Transparent,Font=new Font("Georgia",9)};root.Controls.Add(status,0,4);RefreshStatus(null);var area=Screen.PrimaryScreen.WorkingArea;Height=Math.Min(680,area.Height-30);Location=new Point(area.Right-Width-16,area.Top+20);
  var updateBox=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2,BackColor=Color.Transparent,Margin=new Padding(3,5,3,0)};updateBox.RowStyles.Add(new RowStyle(SizeType.Absolute,30));updateBox.RowStyles.Add(new RowStyle(SizeType.Percent,100));
  updateButton=new WaterButton{Name="UpdateButton",Text="Обновить",Dock=DockStyle.Fill,Font=new Font("Georgia",10),Margin=new Padding(12,0,12,0)};updateButton.Click+=delegate{updates.Click();};
  updateStatus=new Label{Name="UpdateStatus",Dock=DockStyle.Fill,Font=new Font("Segoe UI",9),TextAlign=ContentAlignment.MiddleCenter,BackColor=Color.Transparent};updateBox.Controls.Add(updateButton,0,0);updateBox.Controls.Add(updateStatus,0,1);root.Controls.Add(updateBox,0,5);updates.Changed+=RefreshUpdate;RefreshUpdate();
 }
 void RefreshUpdate(){updateButton.Enabled=!updates.Busy;updateButton.Text=updates.Busy?"Подождите…":"Обновить";updateButton.Active=updates.Available;updateButton.Invalidate();updateStatus.Text=(updates.Available?"⚑ ":"")+updates.Status;updateStatus.ForeColor=updates.Available?Color.FromArgb(43,110,67):Color.FromArgb(104,91,75);updateStatus.AccessibleName=updates.Status;}
 protected override void Dispose(bool disposing){if(disposing&&updates!=null)updates.Changed-=RefreshUpdate;base.Dispose(disposing);}
 static bool Hidden(string s){return s.StartsWith("Убрать шары")||s.StartsWith("Снег: управление")||s.StartsWith("Частота")||s.StartsWith("Снеговик у")||s.StartsWith("Пингвин для")||s.StartsWith("Панель управления");}
 static string Short(string s){if(s.StartsWith("Снег по"))return "Падающий снег";if(s.StartsWith("Сугробы "))return "Сугробы";if(s.StartsWith("Гирлянды:"))return s;if(s.StartsWith("Пингвины убирают"))return "Пингвин с лопатой";if(s.StartsWith("Санта с"))return "Санта по расписанию";if(s.StartsWith("Намести"))return "Намести снег";if(s.StartsWith("Показать Санту"))return "Санта сейчас";if(s.StartsWith("Убрать пойманных"))return "Убрать пингвинов";if(s.StartsWith("Убрать живых"))return "Убрать снеговиков";int i=s.IndexOf('•');return i>0?s.Substring(0,i).Trim():s;}
 void AddItem(ToolStripItem item,ref int count){var model=item as ToolStripMenuItem;if(model==null||!model.Enabled||Hidden(model.Text))return;if(model.HasDropDownItems){foreach(ToolStripItem child in model.DropDownItems)AddItem(child,ref count);return;}var button=new WaterButton{Text=Short(model.Text),Width=204,Height=64,Anchor=AnchorStyles.None,Margin=new Padding(3)};button.Click+=delegate{model.PerformClick();RefreshStatus(null);};grid.Controls.Add(button,0,count);count++;links.Add(Tuple.Create(button,model));}
 internal void EnsureVisible(){bool visible=false;foreach(var screen in Screen.AllScreens)if(screen.WorkingArea.IntersectsWith(Bounds))visible=true;if(!visible){var area=Screen.PrimaryScreen.WorkingArea;Location=new Point(area.Right-Width-16,area.Top+20);}}
 internal void RefreshStatus(string ignored){foreach(var link in links){link.Item1.Text=(link.Item2.Checked?"✓ ":"")+Short(link.Item2.Text);link.Item1.Active=link.Item2.Checked;link.Item1.Invalidate();}play.Text=keys.Enabled?"ИГРОВОЙ РЕЖИМ ВКЛЮЧЁН":"ВКЛЮЧИТЬ ИГРОВОЙ РЕЖИМ";play.Active=keys.Enabled;play.Invalidate();status.Text=keys.Enabled?"S — снеговик     P — пингвин\nEsc — вернуть обычный ввод":keys.Status;}
}
internal sealed partial class Controller {
 WinterPanel panel;QuickKeys quickKeys;UpdateClient updates;double panelAt;
 void InitPanel(ContextMenuStrip menu){quickKeys=new QuickKeys(QuickSnowman,QuickPenguin,TogglePanel);updates=new UpdateClient(dispatch,delegate{ExitThread();});panel=new WinterPanel(menu,quickKeys,updates);quickKeys.Changed=delegate{if(panel!=null)panel.RefreshStatus(null);};panel.Show();}
 void TogglePanel(){if(panel==null)return;if(panel.Visible){quickKeys.SetEnabled(false);panel.Hide();}else{panel.EnsureVisible();panel.Show();}}
 void QuickSnowman(){double now=watch.Elapsed.TotalSeconds;if(now-lastSnowmanSpawn<.12)return;lastSnowmanSpawn=now;SpawnSnowman();}
 void QuickPenguin(){double now=watch.Elapsed.TotalSeconds;if(now-lastPenguinSpawn<.12)return;lastPenguinSpawn=now;SpawnPet();}
 void UpdatePanel(double now){if(panel==null||now<panelAt)return;panelAt=now+.25;panel.RefreshStatus(null);}
}
}
